197	            }
198	            FrameItem::Image(image, size, _) => {
199	                image::render_image(canvas, state.pre_translate(*pos), image, *size);
200	            }
201	            FrameItem::Link(_, _) => {}
202	            FrameItem::Tag(_) => {}
203	        }
