3	use pixglyph::Bitmap;
4	use tiny_skia as sk;
5	use ttf_parser::{GlyphId, OutlineBuilder};
6	use typst_library::layout::{Abs, Axes, Point, Size};
7	use typst_library::text::color::{glyph_frame, should_outline};
8	use typst_library::text::{FontInstance, TextItem};
9	use typst_library::visualize::{FixedStroke, Paint};
10	
11	use crate::paint::{self, GradientSampler, PaintSampler, TilingSampler};
12	use crate::{AbsExt, State, shape};
13	
14	/// Render a text run into the canvas.
15	pub fn render_text(canvas: &mut sk::Pixmap, state: State, text: &TextItem) {
16	    let mut x = Abs::zero();
17	    let mut y = Abs::zero();
18	    for glyph in &text.glyphs {
19	        let id = GlyphId(glyph.id);
20	        let x_offset = x + glyph.x_offset.at(text.size);
21	        let y_offset = y + glyph.y_offset.at(text.size);
22	
23	        if should_outline(&text.font, id) {
24	            let state = state.pre_translate(Point::new(x_offset, -y_offset));
25	            render_outline_glyph(canvas, state, text, id);
26	        } else {
27	            let upem = text.font.units_per_em();
28	            let text_scale = text.size / upem;
29	            let state = state
30	                .pre_translate(Point::new(x_offset, -y_offset))
31	                .pre_scale(Axes::new(text_scale, text_scale));
32	
33	            if let Some(frame) = glyph_frame(&text.font, glyph.id) {
34	                crate::render_frame(canvas, state, &frame.into());
35	            }
36	        }
37	
38	        x += glyph.x_advance.at(text.size);
39	        y += glyph.y_advance.at(text.size);
40	    }
41	}
42	
43	/// Render an outline glyph into the canvas. This is the "normal" case.
44	fn render_outline_glyph(
45	    canvas: &mut sk::Pixmap,
46	    state: State,
47	    text: &TextItem,
48	    id: GlyphId,
49	) -> Option<()> {
50	    let ts = &state.transform;
51	    let ppem = text.size.to_f32() * ts.sy;
52	
53	    // Render a glyph directly as a path. This only happens when the fast glyph
54	    // rasterization can't be used due to very large text size or weird
55	    // scale/skewing transforms.
56	    if ppem > 100.0
57	        || ppem < 0.0
58	        || ts.kx != 0.0
59	        || ts.ky != 0.0
60	        || ts.sx != ts.sy
61	        || text.stroke.is_some()
62	    {
63	        let path = {
64	            let mut builder = WrappedPathBuilder(sk::PathBuilder::new());
65	            text.font.ttf().outline_glyph(id, &mut builder)?;
66	            builder.0.finish()?
67	        };
68	
69	        let scale = text.size.to_f32() / text.font.units_per_em() as f32;
70	
71	        let mut pixmap = None;
72	
73	        let rule = sk::FillRule::default();
74	
75	        // Flip vertically because font design coordinate
76	        // system is Y-up.
77	        let ts = ts.pre_scale(scale, -scale);
78	        let state_ts = state.pre_concat(sk::Transform::from_scale(scale, -scale));
79	        let paint =
80	            paint::to_sk_paint(&text.fill, state_ts, true, &mut pixmap, None, false);
81	        canvas.fill_path(&path, &paint, rule, ts, state.mask);
82	
83	        if let Some(FixedStroke { paint, thickness, cap, join, dash, miter_limit }) =
84	            &text.stroke
85	            && thickness.to_f32() > 0.0
86	        {
87	            let dash = dash.as_ref().and_then(shape::to_sk_dash_pattern);
88	
89	            let paint =
90	                paint::to_sk_paint(paint, state_ts, true, &mut pixmap, None, false);
91	            let stroke = sk::Stroke {
92	                width: thickness.to_f32() / scale, // When we scale the path, we need to scale the stroke width, too.
93	                line_cap: shape::to_sk_line_cap(*cap),
94	                line_join: shape::to_sk_line_join(*join),
95	                dash,
96	                miter_limit: miter_limit.get() as f32,
97	            };
98	
99	            canvas.stroke_path(&path, &paint, &stroke, ts, state.mask);
100	        }
101	        return Some(());
102	    }
103	
104	    // Rasterize the glyph with `pixglyph`.
105	    #[comemo::memoize]
106	    fn rasterize(
107	        font: &FontInstance,
108	        id: GlyphId,
109	        x: u32,
110	        y: u32,
111	        size: u32,
