285	pub fn to_sk_color(color: ProcessColor) -> sk::Color {
286	    let (r, g, b, a) = color.to_rgb().into_components();
287	    sk::Color::from_rgba(r, g, b, a)
288	        .expect("components must always be in the range [0..=1]")
289	}
290	
291	pub fn to_sk_color_u8(color: ProcessColor) -> sk::ColorU8 {
292	    let (r, g, b, a) = color.to_rgb().into_format::<u8, u8>().into_components();
293	    sk::ColorU8::from_rgba(r, g, b, a)
294	}
295	
296	pub fn render_tiling_frame(state: &State, tilings: &Tiling) -> sk::Pixmap {
297	    let size = tilings.size() + tilings.spacing();
298	    let mut canvas = sk::Pixmap::new(
299	        (size.x.to_f32() * state.pixel_per_pt).round() as u32,
300	        (size.y.to_f32() * state.pixel_per_pt).round() as u32,
301	    )
302	    .unwrap();
303	
304	    // Render the tilings into a new canvas.
305	    let ts = sk::Transform::from_scale(state.pixel_per_pt, state.pixel_per_pt);
306	    let temp_state = State::new(tilings.size(), ts, state.pixel_per_pt);
307	    crate::render_frame(&mut canvas, temp_state, tilings.frame());
308	    canvas
309	}
